#include <bits/stdc++.h>using namespace std;using ll = long long; int main() {	// your code goes here	int T;	cin >> T;		while(T --){	    int n;	    cin >> n;	    	    vector<int>a(n) , b(n);	    	    for(int i = 0 ; i < n ; i ++){	        cin >> a[i] ;	    }	    	    for(int i = 0 ; i < n ; i ++){	        cin >> b[i];	    }	    	    //we cant change the order 	    //we just interleave elements	    //so sorting here gives wrong ans         unordered_map<int , int>mp1 , mp2;                for(int i = 0 ; i < n ;  ){            int j = i;            while(j < n && a[i] == a[j]){                j ++;            }                        mp1[a[i]] = max(mp1[a[i]] , j - i);            i = j;        }                for(int i = 0 ; i < n ;  ){            int j = i;            while(j < n && b[i] == b[j]){                j ++;            }                        mp2[b[i]] = max(mp2[b[i]] , j - i);            i = j;        }                ll ans = 0;                //Now iterate on one map and append the maxVal        for(auto [val , cnt] : mp1){            ans = max(ans , 1LL * cnt + 1LL * mp2[val]);        }                for(auto [val , cnt] : mp2){            ans = max(ans , 1LL * cnt + 1LL * mp1[val]);        }                cout << ans << endl;	    	} }